def solve(inp):
    inp=np.array(inp); H,W=inp.shape
    sep_r=[i for i in range(H) if len(set(inp[i]))==1]
    sep_c=[j for j in range(W) if len(set(inp[:,j]))==1]
    rs=[0]+sorted(sep_r)+[H]; cs=[0]+sorted(sep_c)+[W]
    out=[[0]*W for _ in range(H)]
    # order: process regions top-to-bottom, left-to-right; fill = max special+5 per region; empty region copies nearest neighbor's fill
    fills=[]
    for a,b in zip(rs[:-1],rs[1:]):
        for c,d in zip(cs[:-1],cs[1:]):
            specs=sorted({inp[r,c_] for r in range(a,b) for c_ in range(c,d) if inp[r,c_]!=0 and inp[r,c_]!=inp[a,c_]}-(5,) if False else {inp[r,c_] for r in range(a,b) for c_ in range(c,d) if inp[r,c_]!=0})
            spec=max(v for v in specs if v!=5)
            fill = spec+5 if spec else (fills[-1] if fills else 0)
            fills.append(fill)
            for r in range(a,b):
                for cc in range(c,d):
                    out[r][cc]=fill
    return [[int(v) for v in r] for r in out]

